for (f in c('inputs/res_1vs97.rds','inputs/res_1vs98.rds')) {
  cat('FILE', basename(f), '\\n')
  obj <- readRDS(f)
  cat('class:', paste(class(obj), collapse=','), '\\n')
  cat('dim:', paste(dim(obj), collapse='x'), '\\n')
  cat('names:', paste(names(obj), collapse=','), '\\n')
  md <- tryCatch(metadata(obj), error=function(e) NULL)
  if ("'!is.null(md)) {
    cat('"'metadata names:', paste(names(md), collapse=','), '\\n')
    for (nm in names(md)) {
      v <- md[[nm]]
      if (is.atomic(v) && length(v) <= 20) cat('metadata', nm, ':', paste(v, collapse='|'), '\\n')
    }
  }
  cat('mcols names:', paste(names(mcols(obj)), collapse=','), '\\n')
  cat('first rowname:', rownames(obj)[1], '\\n')
}
RS"

